// ─── File: src/test/java/com/bank/jmm/JMMEvolutionTest.java ───
package com.bank.jmm;

import org.junit.jupiter.api.Test;
import java.lang.invoke.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class JMMEvolutionTest {

    // ═══ Java 5: volatile DCL works correctly ═══
    static class Singleton {
        private static volatile Singleton instance;  // volatile! (Java 5+ required!)
        private final String config;

        private Singleton() {
            config = "DB_URL=jdbc:postgresql://localhost/bank";
        }

        static Singleton getInstance() {
            if (instance == null) {
                synchronized (Singleton.class) {
                    if (instance == null) {
                        instance = new Singleton();
                    }
                }
            }
            return instance;
        }
    }

    @Test
    void dclSingleton_worksWithVolatile() throws InterruptedException {
        int threads = 50;
        CountDownLatch latch = new CountDownLatch(threads);
        Singleton[] results = new Singleton[threads];

        for (int i = 0; i < threads; i++) {
            final int idx = i;
            new Thread(() -> {
                results[idx] = Singleton.getInstance();
                latch.countDown();
            }).start();
        }
        latch.await();

        for (Singleton s : results) {
            assertThat(s).isSameAs(results[0]);  // all same instance!
            assertThat(s.config).isNotNull();      // fully initialized!
        }
    }

    // ═══ Java 5: final fields safe publication ═══
    record Account(String id, int balance) {}  // final fields (record)!

    @Test
    void finalFields_safePublication() throws InterruptedException {
        Account[] shared = {null};
        CountDownLatch written = new CountDownLatch(1);

        new Thread(() -> {
            shared[0] = new Account("SAV2001", 100000);
            written.countDown();
        }).start();
        written.await();

        // final fields guaranteed visible after constructor!
        assertThat(shared[0].id()).isEqualTo("SAV2001");
        assertThat(shared[0].balance()).isEqualTo(100000);
    }

    // ═══ Java 9: VarHandle ═══
    int counter = 0;

    @Test
    void varHandle_fineGrainedAccess() throws Exception {
        VarHandle vh = MethodHandles.lookup()
            .findVarHandle(JMMEvolutionTest.class, "counter", int.class);

        vh.setVolatile(this, 42);
        assertThat((int) vh.getVolatile(this)).isEqualTo(42);

        boolean swapped = vh.compareAndSet(this, 42, 100);
        assertThat(swapped).isTrue();
        assertThat((int) vh.getVolatile(this)).isEqualTo(100);
    }

    // ═══ Java 21: virtual threads ═══
    @Test
    void virtualThreads_lightweight() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1000);
        for (int i = 0; i < 1000; i++) {
            Thread.ofVirtual().start(() -> {
                try { Thread.sleep(10); } catch (InterruptedException e) { }
                latch.countDown();
            });
        }
        latch.await(30, TimeUnit.SECONDS);
        assertThat(latch.getCount()).isEqualTo(0);
    }
}
